// ---------------------------------------------------------------------------
// joint_itq scenarios
// ---------------------------------------------------------------------------

fn check_itq(rec: &serde_json::Value) {
    let scenario = rec["scenario"].as_str().unwrap();
    let u_hat = flat_f64(&rec["inputs"]["u_hat"]);
    let v_hat = flat_f64(&rec["inputs"]["v_hat"]);
    let kwargs = &rec["inputs"]["kwargs"];
    let max_iter = kwargs["max_iter"].as_u64().unwrap() as usize;
    let tol = kwargs["tol"].as_f64().unwrap();
    let seed = kwargs["seed"].as_u64().unwrap();
    let (dout, rank) = shape2(&shape_of(&rec["inputs"]["u_hat"]));
    let (din, _) = shape2(&shape_of(&rec["inputs"]["v_hat"]));
    let (u_t, v_t, n_iter, converged) =
        core::joint_itq(&u_hat, &v_hat, dout, din, rank, max_iter, tol, seed)
            .unwrap_or_else(|e| panic!("{scenario}: {e}"));
    let numpy_rec = face_rec(rec, "numpy-reference").unwrap();
    assert_eq!(
        u_t,
        flat_i8(&numpy_rec["u_t"]),
        "{scenario}: u_t vs numpy-reference"
    );
    assert_eq!(
        v_t,
        flat_i8(&numpy_rec["v_t"]),
        "{scenario}: v_t vs numpy-reference"
    );
    assert_eq!(n_iter, numpy_rec["n_iter"].as_u64().unwrap() as usize);
    assert_eq!(converged, numpy_rec["converged"].as_bool().unwrap());
    if let Some(rep_u) = numpy_rec.get("repeat_u_t") {
        // deterministic-seed scenario: byte-identical repeats
        assert_eq!(u_t, flat_i8(rep_u), "{scenario}: repeat u_t");
        assert_eq!(
            v_t,
            flat_i8(&numpy_rec["repeat_v_t"]),
            "{scenario}: repeat v_t"
        );
        assert_eq!(
            n_iter,
            numpy_rec["repeat_n_iter"].as_u64().unwrap() as usize,
            "{scenario}: repeat n_iter"
        );
    }
    if let Some(pyo3) = face_rec(rec, "pyo3") {
        assert_eq!(u_t, flat_i8(&pyo3["u_t"]), "{scenario}: u_t face parity");
        assert_eq!(v_t, flat_i8(&pyo3["v_t"]), "{scenario}: v_t face parity");
        assert_eq!(n_iter, pyo3["n_iter"].as_u64().unwrap() as usize);
        assert_eq!(converged, pyo3["converged"].as_bool().unwrap());
    }
}

#[test]
fn parity_itq_converged() {
    for rec in load_scenarios("joint_itq.json") {
        if rec["scenario"] == "itq_converged" {
            check_itq(&rec);
        }
    }
}

